window.VO = [{"id":"n01","text":"Your partner in crime is in the next room.","at":0.08,"t0":0.04,"t1":2.195},{"id":"n02","text":"And he's talking.","at":6.49,"t0":3.245,"t1":4.345},{"id":"d01","text":"Whoever talks walks out tonight.","at":9.69,"t0":4.845,"t1":7.35},{"id":"d02","text":"The other one does ten years.","at":15.3,"t0":7.65,"t1":9.92},{"id":"d03","text":"You both talk? Five each.","at":21.34,"t0":10.67,"t1":12.93},{"id":"n03","text":"If nobody talks, a year each.","at":26.56,"t0":13.28,"t1":15.155},{"id":"n04","text":"Stay silent, or talk?","at":33.21,"t0":16.605,"t1":17.96},{"id":"f01","text":"Nah. My partner won't talk.","at":38.52,"t0":19.26,"t1":20.82},{"id":"f02","text":"I'd bet ten years on it.","at":42.24,"t0":21.12,"t1":22.64},{"id":"n05","text":"He was talking about you.","at":46.38,"t0":23.19,"t1":24.555},{"id":"n06","text":"If you stayed silent, you both do a year.","at":50.11,"t0":25.055,"t1":27.37},{"id":"n07","text":"If you talked, you walk out tonight, and he does the ten.","at":55.64,"t0":27.82,"t1":30.655},{"id":"n08","text":"For trusting you.","at":62.01,"t0":31.005,"t1":32.015},{"id":"n09","text":"Talking was the safe move.","at":66.13,"t0":33.065,"t1":34.62},{"id":"n10","text":"That's the deal.","at":69.84,"t0":34.92,"t1":35.84},{"id":"n11","text":"It doesn't need a bad friend.","at":72.98,"t0":36.49,"t1":38.01},{"id":"n12","text":"It just needs you to doubt a good one.","at":76.62,"t0":38.31,"t1":40.11},{"id":"n13","text":"Now try it on your partner in crime.","at":83.62,"t0":41.81,"t1":43.79},{"id":"n14","text":"And don't warn them.","at":88.18,"t0":44.09,"t1":45.19},{"id":"n15","text":"Unless they just tried it on you.","at":91.58,"t0":45.79,"t1":47.38},{"id":"n16","text":"Next case.","at":96.16,"t0":48.08,"t1":48.985}];
